package web

import (
	"fmt"
	"html/template"
	"net/http"
	"strings"
	"time"

	"github.com/zhangchengzhen42-tech/Shop/internal/app"
)

type templates struct{ loginTemplate, dashboardTemplate *template.Template }

type pageData struct {
	User      app.User
	Dashboard app.Dashboard
	Summary   app.Summary
	Message   string
}

func newTemplates() *templates {
	functions := template.FuncMap{
		"money": func(value int64) string { return fmt.Sprintf("¥%.2f", float64(value)/100) },
		"time": func(value time.Time) string {
			if value.IsZero() {
				return "—"
			}
			return value.Local().Format("2006-01-02 15:04:05")
		},
		"status":  statusText,
		"hasRole": func(user app.User, role string) bool { return user.Role == role },
		"eq":      func(left, right string) bool { return left == right },
	}
	dashboard := strings.Replace(dashboardHTML, "{{template \"style\"}}", "<style>{{template \"style\"}}</style>", 1)
	dashboard = strings.Replace(dashboard, "{{if .PaymentTx}}{{.PaymentTx}}{{else}}—{{end}}", "{{if .PaymentTx}}{{.PaymentTx}}{{else}}—{{end}}{{if .Tracking}}<br><span class=\"muted\">{{.Carrier}} · {{.Tracking}}</span>{{end}}", 1)
	dashboard = strings.Replace(dashboard, "name=\"reason\" placeholder=\"审核原因\"", "name=\"reason\" placeholder=\"审核原因\" required", 1)
	dashboard = strings.Replace(dashboard, "{{if hasRole .User \"channel\"}}", serviceRetryHTML+"{{if hasRole .User \"channel\"}}", 1)
	dashboard = strings.Replace(dashboard, "</main></div></body></html>", operationsRecordsHTML+"</main></div></body></html>", 1)
	return &templates{loginTemplate: template.Must(template.New("login").Funcs(functions).Parse(loginHTML)), dashboardTemplate: template.Must(template.New("dashboard").Funcs(functions).Parse(dashboard))}
}

func (t *templates) login(w http.ResponseWriter, message string) {
	_ = t.loginTemplate.Execute(w, map[string]string{"Message": message})
}
func (t *templates) dashboard(w http.ResponseWriter, data pageData) {
	_ = t.dashboardTemplate.Execute(w, data)
}

func statusText(status string) string {
	values := map[string]string{"PENDING": "待付款", "AWAIT_SHIPMENT": "待发货", "REFUND_REVIEW": "退款审核中", "REFUNDING": "退款处理中", "REFUNDED": "已退款", "SHIPPED": "已发货", "CLOSED": "已关闭", "REVIEW": "待审核", "REJECTED": "已拒绝", "PENDING_CHANNEL": "待渠道处理", "FAILED": "失败待重试", "SUCCESS": "退款成功", "PENDING_REFUND": "待退款"}
	if value, ok := values[status]; ok {
		return value
	}
	return status
}

const serviceRetryHTML = `{{if hasRole .User "service"}}<section class="panel"><h2>退款失败重试</h2>{{range .Dashboard.Refunds}}{{if eq .Status "FAILED"}}<div class="item"><strong>{{.ID}}</strong><div class="muted">订单 {{if .OrderID}}{{.OrderID}}{{else}}迟到支付异常 {{.ExceptionID}}{{end}} · {{money .Amount}}</div><div class="muted">最近结果：{{.Reason}}</div><form class="inline" method="post" action="/refunds/retry" style="margin-top:8px"><input type="hidden" name="refund_id" value="{{.ID}}"><input name="reason" placeholder="重试原因" required><button>发起重试</button></form></div>{{end}}{{end}}</section>{{end}}`

const operationsRecordsHTML = `{{if hasRole .User "operations"}}<section class="panel"><h2>交易与履约记录</h2><div class="split"><div><h3>收款记录</h3><table><thead><tr><th>订单</th><th>渠道交易号</th><th>金额</th><th>结果</th></tr></thead><tbody>{{range .Dashboard.Payments}}<tr><td>{{if .OrderID}}{{.OrderID}}{{else}}—{{end}}</td><td>{{.ChannelTx}}</td><td>{{money .Amount}}</td><td>{{.Result}}{{if .Reason}}<br><span class="muted">{{.Reason}}</span>{{end}}</td></tr>{{end}}</tbody></table></div><div><h3>退款记录</h3><table><thead><tr><th>关联对象</th><th>金额</th><th>状态</th><th>原因</th></tr></thead><tbody>{{range .Dashboard.Refunds}}<tr><td>{{if .OrderID}}{{.OrderID}}{{else}}{{.ExceptionID}}{{end}}</td><td>{{money .Amount}}</td><td>{{status .Status}}</td><td>{{.Reason}}</td></tr>{{end}}</tbody></table></div></div><div style="margin-top:18px"><h3>发货记录</h3><table><thead><tr><th>订单</th><th>承运方</th><th>运单号</th><th>登记时间</th></tr></thead><tbody>{{range .Dashboard.Shipments}}<tr><td>{{.OrderID}}</td><td>{{.Carrier}}</td><td>{{.Tracking}}</td><td>{{time .CreatedAt}}</td></tr>{{end}}</tbody></table></div></section>{{end}}`

const loginHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Shop 交易系统</title><style>body{margin:0;background:#f4f6f9;color:#132033;font:14px/1.45 Arial,"Microsoft YaHei",sans-serif}.login{display:grid;place-items:center;min-height:100vh}.login-card{width:380px;background:#fff;border:1px solid #e3e8ef;border-radius:8px;padding:28px;box-shadow:0 12px 36px #dce2ea}.login-card h1{margin:0}.login-card p,small{color:#6d7887}.login-card label{display:block;margin:20px 0 8px;font-weight:700}select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #ccd5df;border-radius:5px;background:#fff}button{border:0;border-radius:5px;padding:9px 12px;background:#132b4a;color:#fff;font-weight:700;cursor:pointer}form button{margin-top:12px;width:100%}.notice{margin:12px 0;background:#eef5ff;color:#155da5;padding:10px;border-radius:5px}</style><body class="login"><main class="login-card"><h1>Shop 交易系统</h1><p>订单、支付、退款与履约演示环境</p>{{if .Message}}<div class="notice">{{.Message}}</div>{{end}}<form method="post"><label>选择可信演示身份</label><select name="user_id"><option value="buyer-1">买家：小聪</option><option value="buyer-2">买家：阿羽</option><option value="buyer-3">买家：陈星</option><option value="ops-1">运营：赵运营</option><option value="warehouse-1">仓库：仓库员</option><option value="service-1">客服：客服员</option><option value="channel-1">模拟支付渠道</option></select><button>进入工作台</button></form><small>身份写入受服务端签名保护的会话 Cookie，请勿通过请求用户编号越权。</small></main></body></html>`

const dashboardHTML = `{{define "style"}}body{margin:0;background:#f4f6f9;color:#132033;font:14px/1.45 Arial,"Microsoft YaHei",sans-serif}.login{display:grid;place-items:center;min-height:100vh}.login-card{width:380px;background:#fff;border:1px solid #e3e8ef;border-radius:8px;padding:28px;box-shadow:0 12px 36px #dce2ea}.login-card h1{margin:0}.login-card p,small{color:#6d7887}.login-card label{display:block;margin:20px 0 8px;font-weight:700}select,input{width:100%;box-sizing:border-box;padding:9px;border:1px solid #ccd5df;border-radius:5px;background:#fff}button{border:0;border-radius:5px;padding:9px 12px;background:#132b4a;color:#fff;font-weight:700;cursor:pointer}form button{margin-top:12px;width:100%}.app{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.side{background:#fff;border-right:1px solid #e3e8ef;padding:24px 16px}.brand{font-size:18px;font-weight:800}.muted{color:#6d7887;font-size:12px}.who{margin:18px 0;padding:12px;background:#f4f7fa;border-radius:6px}.main{padding:28px;max-width:1380px}.top{display:flex;justify-content:space-between;gap:20px;align-items:start}.top h1{margin:0}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:18px 0}.metric,.panel{background:#fff;border:1px solid #e3e8ef;border-radius:8px}.metric{padding:14px}.metric strong{display:block;font-size:22px;margin-top:6px}.panel{padding:18px;margin:14px 0}.panel h2{font-size:16px;margin:0 0 12px}.products,.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.product,.item{border:1px solid #e3e8ef;border-radius:7px;padding:14px}.price{font-size:20px;font-weight:800}.stock{height:6px;background:#e7ebf0;border-radius:6px;margin:8px 0}.stock i{display:block;height:100%;background:#1d8c68;border-radius:6px}.status{display:inline-block;background:#e8f1ff;color:#1262b3;border-radius:20px;padding:3px 8px;font-size:12px;font-weight:700}.closed,.failed{background:#fde7e7;color:#aa3030}.good{background:#e4f7ee;color:#08724e}.warn{background:#fff3dc;color:#8d5a14}.notice{margin:12px 0;background:#eef5ff;color:#155da5;padding:10px;border-radius:5px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e8edf2;vertical-align:top}th{color:#657386;background:#f8fafc}.inline{display:inline-flex;gap:6px;align-items:center}.inline input{width:auto;min-width:110px}.danger{background:#a53030}.outline{background:#fff;color:#223c58;border:1px solid #ccd5df}.audit{max-height:280px;overflow:auto}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.products,.split{grid-template-columns:1fr}.app{grid-template-columns:1fr}.side{display:none}} {{end}}
{{template "style"}}<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Shop 交易系统</title><body><div class="app"><aside class="side"><div class="brand">Shop 交易台</div><div class="muted">订单 · 库存 · 资金 · 履约</div><div class="who"><strong>{{.User.Name}}</strong><br><span class="muted">{{.User.Role}}</span></div><form action="/logout" method="post"><button class="outline">退出当前身份</button></form></aside><main class="main"><header class="top"><div><h1>{{.User.Name}}的工作台</h1><p class="muted">所有交易状态由服务端领域服务和 SQLite 数据库维护</p></div><form class="inline" action="/orders/expire" method="post"><button class="outline">检查超时订单</button></form></header>{{if .Message}}<div class="notice">{{.Message}}</div>{{end}}<section class="metrics"><div class="metric"><span class="muted">商品可售</span><strong>{{.Summary.Available}} 件</strong></div><div class="metric"><span class="muted">已收款</span><strong>{{money .Summary.ReceivedCents}}</strong></div><div class="metric"><span class="muted">已退款</span><strong>{{money .Summary.RefundedCents}}</strong></div><div class="metric"><span class="muted">待发货</span><strong>{{.Summary.AwaitShipment}} 单</strong></div><div class="metric"><span class="muted">待付款</span><strong>{{.Summary.PendingPayment}} 单</strong></div></section>
{{if hasRole .User "buyer"}}<section class="panel"><h2>在售商品</h2><div class="products">{{range .Dashboard.Products}}<article class="product"><strong>{{.Name}}</strong><div class="muted">商品编号 {{.ID}} · 订单保存当前价格快照</div><div class="price">{{money .Price}}</div><div class="stock"><i style="width:{{if .OnSale}}80{{else}}0{{end}}%"></i></div><div class="muted">可售 {{.Available}} 件 · {{if .OnSale}}上架中{{else}}已下架{{end}}</div><form class="inline" method="post" action="/orders" style="margin-top:12px"><input type="hidden" name="product_id" value="{{.ID}}"><select name="quantity"><option value="1">1 件</option><option value="2">2 件</option></select><button {{if not .OnSale}}disabled{{end}}>创建订单</button></form></article>{{end}}</div></section>{{end}}
<section class="panel"><h2>{{if hasRole .User "buyer"}}我的订单{{else}}订单队列{{end}}</h2><table><thead><tr><th>订单</th><th>商品与金额</th><th>状态</th><th>支付</th><th>操作</th></tr></thead><tbody>{{range .Dashboard.Orders}}<tr><td><strong>{{.ID}}</strong><br><span class="muted">{{time .CreatedAt}}</span></td><td>{{.ProductName}} × {{.Quantity}}<br><strong>{{money .Total}}</strong></td><td><span class="status">{{status .Status}}</span></td><td>{{if .PaymentTx}}{{.PaymentTx}}{{else}}—{{end}}</td><td>{{if and (hasRole $.User "buyer") (eq .Status "PENDING")}}<form class="inline" method="post" action="/orders/cancel"><input type="hidden" name="order_id" value="{{.ID}}"><button class="danger">取消</button></form>{{end}}{{if and (hasRole $.User "buyer") (eq .Status "AWAIT_SHIPMENT")}}<form class="inline" method="post" action="/refunds/request"><input type="hidden" name="order_id" value="{{.ID}}"><button class="outline">申请退款</button></form>{{end}}{{if and (hasRole $.User "warehouse") (eq .Status "AWAIT_SHIPMENT")}}<form class="inline" method="post" action="/orders/ship"><input type="hidden" name="order_id" value="{{.ID}}"><input name="carrier" value="顺丰速运"><input name="tracking" placeholder="运单号"><button>发货</button></form>{{end}}</td></tr>{{end}}</tbody></table></section>
{{if hasRole .User "service"}}<div class="split"><section class="panel"><h2>退款审核</h2>{{range .Dashboard.Refunds}}{{if eq .Status "REVIEW"}}<div class="item"><strong>{{.ID}}</strong><div class="muted">订单 {{.OrderID}} · {{money .Amount}}</div><form class="inline" method="post" action="/refunds/review"><input type="hidden" name="refund_id" value="{{.ID}}"><input name="reason" placeholder="审核原因"><button name="decision" value="approve">同意</button><button class="danger" name="decision" value="reject">拒绝</button></form></div>{{end}}{{end}}</section><section class="panel"><h2>迟到支付异常</h2>{{range .Dashboard.Exceptions}}<div class="item"><strong>{{.ID}}</strong><div class="muted">原订单 {{.OrderID}} · {{.ChannelTx}} · {{money .Amount}}</div><div>{{.Reason}}</div>{{if eq .Status "PENDING_REFUND"}}<form method="post" action="/exceptions/refund" style="margin-top:8px"><input type="hidden" name="exception_id" value="{{.ID}}"><button>发起退款</button></form>{{end}}</div>{{end}}</section></div>{{end}}
{{if hasRole .User "channel"}}<div class="split"><section class="panel"><h2>发送付款通知</h2><p class="muted">签名无效、金额不符、未知订单和迟到付款均将留存处理记录。</p><form method="post" action="/channel/payment"><label>订单号</label><input name="order_id" placeholder="ORD-..."><label>渠道交易号</label><input name="channel_tx" placeholder="PAY-..."><label>金额（分）</label><input name="amount_cents" value="10000"><label>验签</label><select name="signature"><option value="valid">有效</option><option value="invalid">无效</option></select><button>发送支付通知</button></form></section><section class="panel"><h2>发送退款通知</h2>{{range .Dashboard.Refunds}}<div class="item"><strong>{{.ID}}</strong> · {{status .Status}} · {{money .Amount}}<form class="inline" method="post" action="/channel/refund" style="margin-top:8px"><input type="hidden" name="refund_id" value="{{.ID}}"><button name="result" value="success">成功</button><button class="danger" name="result" value="failed">失败</button></form></div>{{end}}</section></div>{{end}}
{{if hasRole .User "operations"}}<section class="panel"><h2>商品维护</h2><div class="products">{{range .Dashboard.Products}}<form class="product" method="post" action="/products/update"><input type="hidden" name="product_id" value="{{.ID}}"><strong>{{.Name}}</strong><div class="muted">历史订单沿用创建时的价格快照</div><label>售价（分）</label><input name="price_cents" value="{{.Price}}"><label>当前可售数量</label><input name="available" value="{{.Available}}"><label>销售状态</label><select name="on_sale"><option value="1" {{if .OnSale}}selected{{end}}>上架</option><option value="0" {{if not .OnSale}}selected{{end}}>下架</option></select><button>保存商品</button></form>{{end}}</div></section><div class="split"><section class="panel"><h2>异常记录</h2>{{range .Dashboard.Exceptions}}<div class="item"><strong>{{.ID}}</strong> <span class="status warn">{{status .Status}}</span><div class="muted">订单 {{.OrderID}} · {{.ChannelTx}} · {{money .Amount}}</div><div>{{.Reason}}</div></div>{{end}}</section><section class="panel audit"><h2>操作审计</h2><table><thead><tr><th>时间</th><th>操作</th><th>详情</th></tr></thead><tbody>{{range .Dashboard.Audits}}<tr><td>{{time .CreatedAt}}</td><td>{{.Actor}} · {{.Action}}</td><td>{{.Detail}}</td></tr>{{end}}</tbody></table></section></div>{{end}}
</main></div></body></html>`
